import numpy as np

def second_order_residual(y, dy, d2y, p, q, ts):
    """Largest |y'' + p y' + q y| over the array ts."""
    ts = np.asarray(ts, dtype=float)
    return float(np.max(np.abs(d2y(ts) + p * dy(ts) + q * y(ts))))

def as_system(p, q):
    """The matrix of x' = A x with x = (y, y'), as a nested list."""
    return [[0, 1], [-q, -p]]
